inserted_questions as (
  insert into public.questions (
    id,
    sport_id,
    difficulty,
    question_text,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    status,
    eligible_for_daily,
    eligible_for_sport_quiz,
    authoring_method,
    source_notes,
    reviewed_at
  )
  select
    gen_random_uuid(),
    sport.id,
    seed.difficulty,
    seed.question_text,
    seed.option_a,
    seed.option_b,
    seed.option_c,
    seed.option_d,
    seed.correct_option,
    'ready',
    true,
    true,
    'ai_assisted',
    seed.source_notes,
    timezone('utc', now())
  from question_seed seed
  join public.sports sport
    on sport.slug = seed.sport_slug
  where not exists (
    select 1
    from public.questions existing
    where existing.sport_id = sport.id
      and lower(btrim(existing.question_text)) = lower(btrim(seed.question_text))
  )
  returning id
)
select count(*) from inserted_questions;
